60	export function calculateTotalPlayed(record: Tier3StateRecord | ChannelStateRecord): number {
61	  return (
62	    record.score_3_count.length +
63	    record.score_4_count.length +
64	    record.score_5_count.length +
65	    record.score_6_count.length +
66	    record.score_7_count.length
67	  );
68	}
