393	
394	  for (const k in tier1MemoryCache) delete tier1MemoryCache[k];
395	  invalidateVinylCache(projectId);
396	
397	  return {
398	    totalActive: 0,
399	    excludedCount: excludedIds.length,
400	  };
401	}
