403	export async function syncTier2ToTier3(projectId: string) {
404	  const tier2Res = await executeOrder<Tier2EventEntry[]>({
405	    project_id: projectId,
406	    tier: '2',
407	    order: { action: 'read_all' },
408	  });
409	  const rawEvents = Array.isArray(tier2Res.data) ? tier2Res.data : [];
410	
411	  // 1. Gather all block events from rawEvents
412	  const blockedPayloadMap: Record<string, { id: string; blocked_at: string }> = {};
413	  for (const evt of rawEvents) {
414	    if (!evt || !evt.id) continue;
415	    const act = (evt.action || '').toLowerCase().trim();
416	    if (act === 'block') {
417	      blockedPayloadMap[evt.id] = {
418	        id: evt.id,
419	        blocked_at: evt.timestamp || new Date().toISOString(),
420	      };
421	    }
422	  }
423	
424	  // 2. Persist new block events to blacklist database
425	  if (Object.keys(blockedPayloadMap).length > 0) {
426	    await executeOrder({
427	      project_id: projectId,
428	      tier: 'blacklist',
429	      order: {
430	        action: 'batch_upsert',
431	        data: blockedPayloadMap,
432	      },
433	    });
434	  }
435	
436	  // 3. Fetch all excluded IDs across blacklist AND bad_kpi
437	  const [blacklistRes, badKpiRes] = await Promise.all([
438	    executeOrder<Record<string, Record<string, unknown>>>({
439	      project_id: projectId,
440	      tier: 'blacklist',
441	      order: { action: 'read_all' },
442	    }),
443	    executeOrder<Record<string, Record<string, unknown>>>({
444	      project_id: projectId,
445	      tier: 'bad_kpi',
446	      order: { action: 'read_all' },
447	    }),
448	  ]);
449	
450	  const allExcludedIds = Array.from(
451	    new Set([
452	      ...Object.keys(blockedPayloadMap),
453	      ...Object.keys(blacklistRes.data || {}),
454	      ...Object.keys(badKpiRes.data || {}),
455	    ])
456	  );
457	
458	  // 4. Purge all excluded IDs from Tier 3 (_3_state.db) and Tier 4 (_4_display.db)
459	  if (allExcludedIds.length > 0) {
460	    await Promise.all([
461	      executeOrder({
462	        project_id: projectId,
463	        tier: '3',
464	        order: { action: 'batch_delete', data: allExcludedIds },
465	      }),
466	      executeOrder({
467	        project_id: projectId,
468	        tier: '4',
469	        order: { action: 'batch_delete', data: allExcludedIds },
470	      }),
471	    ]);
472	  }
473	
474	  // 5. Purge from Tier 1 (_1_static.db)
475	  let staticSynced = false;
476	  try {
477	    await syncRawinfoMinusBlacklistToTier1(projectId);
478	    staticSynced = true;
479	  } catch (e) {
480	    console.error('[Blacklist->Static] Lỗi trừ ID khỏi _1_static.db:', e);
481	  }
482	
483	  // 6. Process non-blocked rating events for Tier 3 tracks and channels
484	  const excludedSet = new Set(allExcludedIds);
485	  const [currentT3, currentChannels] = await Promise.all([
486	    fetchTier3State(projectId),
487	    fetchChannelState(projectId),
488	  ]);
489	
490	  const stateMap: Record<string, Tier3StateRecord> = {};
491	  currentT3.forEach((r) => {
492	    if (!excludedSet.has(r.id)) {
493	      stateMap[r.id] = r;
494	    }
495	  });
496	
497	  const channelMap: Record<string, ChannelStateRecord> = { ...currentChannels };
498	  const modifiedTrackIds = new Set<string>();
499	  const modifiedChannelIds = new Set<string>();
500	
501	  for (const evt of rawEvents) {
502	    if (!evt || !evt.id || excludedSet.has(evt.id)) continue;
503	    const act = (evt.action || '').toLowerCase().trim();
504	    if (act === 'block') continue;
505	
506	    // Check if event is targeted to an entire channel
507	    if (evt.target_type === 'channel' || (evt.channel_id && evt.channel_id === evt.id)) {
508	      const chId = evt.channel_id || evt.id;
509	      if (!channelMap[chId]) {
510	        channelMap[chId] = {
511	          channel_id: chId,
512	          channel_name: evt.channel_name || '',
513	          score_3_count: [],
514	          score_4_count: [],
515	          score_5_count: [],
516	          score_6_count: [],
517	          score_7_count: [],
518	          timeblock_arc0: 0,
519	          timeblock_arc1: 0,
520	          timeblock_arc2: 0,
521	          timeblock_arc3: 0,
522	          timeblock_arc4: 0,
523	          unlock_date: null,
524	        };
525	      }
526	      const ch = channelMap[chId];
527	
528	      if (act === '3+' || act === 'cancel' || act === 'downvote') {
529	        ch.score_3_count.push(evt.timestamp);
530	      } else if (act === '4+') {
531	        ch.score_4_count.push(evt.timestamp);
532	      } else if (act === '5+' || act === 'continue') {
533	        ch.score_5_count.push(evt.timestamp);
534	      } else if (act === '6+' || act === 'upvote') {
535	        ch.score_6_count.push(evt.timestamp);
536	      } else if (act === '7+' || act === 'overflow') {
537	        ch.score_7_count.push(evt.timestamp);
538	      }
539	
540	      if (evt.timeblock) {
541	        const blocks = Array.isArray(evt.timeblock) ? evt.timeblock : [evt.timeblock];
542	        blocks.forEach((b) => {
543	          if (/arc\s*zero|kick/i.test(b)) ch.timeblock_arc0++;
544	          else if (/arc\s*0?1|morning/i.test(b)) ch.timeblock_arc1++;
545	          else if (/arc\s*0?2|battle/i.test(b)) ch.timeblock_arc2++;
546	          else if (/arc\s*0?3|night/i.test(b)) ch.timeblock_arc3++;
547	          else if (/arc\s*0?4|sacred/i.test(b)) ch.timeblock_arc4++;
548	        });
549	      }
550	      modifiedChannelIds.add(chId);
551	      continue;
552	    }
553	
554	    // Otherwise it's a track-level event
555	    if (!stateMap[evt.id]) {
556	      stateMap[evt.id] = {
557	        id: evt.id,
558	        score_3_count: [],
559	        score_4_count: [],
560	        score_5_count: [],
561	        score_6_count: [],
562	        score_7_count: [],
563	        timeblock_arc0: 0,
564	        timeblock_arc1: 0,
565	        timeblock_arc2: 0,
566	        timeblock_arc3: 0,
567	        timeblock_arc4: 0,
568	        unlock_date: null,
569	      };
570	    }
571	    const r = stateMap[evt.id];
572	
573	    if (act === '3+' || act === 'cancel' || act === 'downvote') {
574	      r.score_3_count.push(evt.timestamp);
575	    } else if (act === '4+') {
576	      r.score_4_count.push(evt.timestamp);
577	    } else if (act === '5+' || act === 'continue') {
578	      r.score_5_count.push(evt.timestamp);
579	    } else if (act === '6+' || act === 'upvote') {
580	      r.score_6_count.push(evt.timestamp);
581	    } else if (act === '7+' || act === 'overflow') {
582	      r.score_7_count.push(evt.timestamp);
583	    }
584	
585	    if (evt.timeblock) {
586	      const blocks = Array.isArray(evt.timeblock) ? evt.timeblock : [evt.timeblock];
587	      blocks.forEach((b) => {
588	        if (/arc\s*zero|kick/i.test(b)) r.timeblock_arc0++;
589	        else if (/arc\s*0?1|morning/i.test(b)) r.timeblock_arc1++;
590	        else if (/arc\s*0?2|battle/i.test(b)) r.timeblock_arc2++;
591	        else if (/arc\s*0?3|night/i.test(b)) r.timeblock_arc3++;
592	        else if (/arc\s*0?4|sacred/i.test(b)) r.timeblock_arc4++;
593	      });
594	    }
595	    modifiedTrackIds.add(evt.id);
596	  }
597	
598	  // 7. Upsert modified track states into tier_3_data
599	  if (modifiedTrackIds.size > 0) {
600	    const t3BatchData: Record<string, Record<string, unknown>> = {};
601	    for (const id of modifiedTrackIds) {
602	      if (excludedSet.has(id)) continue;
603	      const r = stateMap[id];
604	      t3BatchData[id] = {
605	        score_3_count: JSON.stringify(r.score_3_count),
606	        score_4_count: JSON.stringify(r.score_4_count),
607	        score_5_count: JSON.stringify(r.score_5_count),
608	        score_6_count: JSON.stringify(r.score_6_count),
609	        score_7_count: JSON.stringify(r.score_7_count),
610	        timeblock_arc0: r.timeblock_arc0,
611	        timeblock_arc1: r.timeblock_arc1,
612	        timeblock_arc2: r.timeblock_arc2,
613	        timeblock_arc3: r.timeblock_arc3,
614	        timeblock_arc4: r.timeblock_arc4,
615	        unlock_date: r.unlock_date,
616	      };
617	    }
618	
619	    await executeOrder({
620	      project_id: projectId,
621	      tier: '3',
622	      order: {
623	        action: 'batch_upsert',
624	        data: t3BatchData,
625	      },
626	    });
627	  }
628	
629	  // 8. Upsert modified channel states into channel_state table
630	  if (modifiedChannelIds.size > 0) {
631	    const chBatchData: Record<string, Record<string, unknown>> = {};
632	    for (const chId of modifiedChannelIds) {
633	      const ch = channelMap[chId];
634	      chBatchData[chId] = {
635	        channel_id: ch.channel_id,
636	        channel_name: ch.channel_name,
637	        score_3_count: JSON.stringify(ch.score_3_count),
638	        score_4_count: JSON.stringify(ch.score_4_count),
639	        score_5_count: JSON.stringify(ch.score_5_count),
640	        score_6_count: JSON.stringify(ch.score_6_count),
641	        score_7_count: JSON.stringify(ch.score_7_count),
642	        timeblock_arc0: ch.timeblock_arc0,
643	        timeblock_arc1: ch.timeblock_arc1,
644	        timeblock_arc2: ch.timeblock_arc2,
645	        timeblock_arc3: ch.timeblock_arc3,
646	        timeblock_arc4: ch.timeblock_arc4,
647	        unlock_date: ch.unlock_date,
648	        updated_at: new Date().toISOString(),
649	      };
650	    }
651	
652	    await executeOrder({
653	      project_id: projectId,
654	      tier: 'channel_state',
655	      order: {
656	        action: 'batch_upsert',
657	        data: chBatchData,
658	      },
659	    });
