990	      const chTimeblock = chState ? getDominantTimeblock(chState) : null;
991	
992	      const effectiveHazard = t4 ? t4.hazard_level : chHazard;
993	      const effectivePlayed = t4 ? t4.played : chPlayed;
994	      const effectiveTimeblock = t4?.timeblock ?? chTimeblock;
995	
996	      // Update statsMap so track stats are populated
997	      if (!t4 && chState) {
998	        statsMap[trackId] = {
999	          hazard_level: effectiveHazard,
1000	          played: effectivePlayed,
1001	          timeblock: effectiveTimeblock,
1002	          unlock_date: chState.unlock_date,
1003	        };
1004	      }
1005	
1006	      return {
1007	        id: trackId,
1008	        title: (v.title as string) || (v.name as string) || `Track ${id}`,
1009	        channel:
1010	          (v.channel_name as string) ||
1011	          (v.channel as string) ||
1012	          (v.artist as string) ||
1013	          'Unknown Origin',
1014	        channel_id: chId,
1015	        duration: (v.duration as number) ?? null,
1016	        hazard_level: effectiveHazard,
1017	        played: effectivePlayed,
1018	        timeblock: effectiveTimeblock,
1019	      };
1020	    })
1021	    .filter((t) => t.id && t.id.length >= 8);
1022	
1023	  const totalCatalogCount = countRes.data?.count !== undefined ? countRes.data.count : tracks.length;
